INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('4c3abd62-faa3-44b2-b4ae-9aeb49bbd0b6', 'yds', 'I don''t like ------- coffee in the morning, but I love it in the afternoon.', '[{"id": "a", "text": "the"}, {"id": "b", "text": "a"}, {"id": "c", "text": "(artikel yok)"}, {"id": "d", "text": "an"}]'::jsonb, 'c', 'Genel bir kategoriden (kahve) bahsedilirken artikel kullanılmaz.', '[{"word": "artikelsiz genel isim", "example": "Music makes me happy.", "meaning": "genel bir kategoriden bahsetme"}]'::jsonb, 'medium', true, 'en', 'the-specific-vs-general', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('6b9601a2-37c8-4ecc-a9f2-7f15bcfc548e', 'yokdil', 'I bought a laptop yesterday. ------- laptop was very expensive.', '[{"id": "a", "text": "A"}, {"id": "b", "text": "The"}, {"id": "c", "text": "(artikel yok)"}, {"id": "d", "text": "An"}]'::jsonb, 'b', 'İkinci kez bahsedilen, artık bilinen bir isim için the kullanılır.', '[{"word": "the (ikinci bahsediş)", "example": "I saw a cat. The cat was black.", "meaning": "daha önce bahsedilmiş, bilinen isim"}]'::jsonb, 'medium', true, 'en', 'the-specific-vs-general', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('84440c6c-8d0c-4151-b147-6aaa1525c101', 'yokdil', 'The news about the merger ------- quite surprising to everyone.', '[{"id": "a", "text": "is"}, {"id": "b", "text": "are"}, {"id": "c", "text": "were"}, {"id": "d", "text": "have been"}]'::jsonb, 'a', 'news sayılamayan bir isimdir ve her zaman tekil fiil alır.', '[{"word": "news (tekil)", "example": "The news is on TV now.", "meaning": "sayılamayan, hep tekil fiil alan isim"}]'::jsonb, 'medium', true, 'en', 'subject-verb-agreement-nouns', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('d7a9d4f1-8793-4ed6-8bac-4b186aa63731', 'toefl', 'The police ------- still investigating the robbery downtown.', '[{"id": "a", "text": "is"}, {"id": "b", "text": "are"}, {"id": "c", "text": "was"}, {"id": "d", "text": "has been"}]'::jsonb, 'b', 'police her zaman çoğul fiil alan bir isimdir.', '[{"word": "police (hep çoğul)", "example": "The police are on their way.", "meaning": "tekil formda olsa da hep çoğul fiil alır"}]'::jsonb, 'medium', true, 'en', 'subject-verb-agreement-nouns', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('ac868756-dbce-4775-8bc3-197479c4a1fd', 'yds', 'This is my ------- car; he just bought it last week.', '[{"id": "a", "text": "brother"}, {"id": "b", "text": "brother''s"}, {"id": "c", "text": "brothers"}, {"id": "d", "text": "of brother"}]'::jsonb, 'b', 'Canlı bir varlık (kardeş) için iyelik ''s kullanılır.', '[{"word": "''s (canlı varlık)", "example": "my brother''s car", "meaning": "insan/hayvan için tercih edilen iyelik yapısı"}]'::jsonb, 'easy', true, 'en', 'possessive-s-vs-of', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('b58faa34-9ea8-4421-b57f-f09f37538bb4', 'yokdil', 'The ------- was covered with snow all winter.', '[{"id": "a", "text": "mountain''s top"}, {"id": "b", "text": "top of the mountain"}, {"id": "c", "text": "top''s mountain"}, {"id": "d", "text": "mountain top''s"}]'::jsonb, 'b', 'Cansız bir nesne (dağ) için genellikle of yapısı tercih edilir.', '[{"word": "of (cansız nesne)", "example": "the top of the mountain", "meaning": "cansız nesneler için tercih edilen yapı"}]'::jsonb, 'medium', true, 'en', 'possessive-s-vs-of', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('ca49099a-82a8-4089-bbbe-00ab154eb036', 'toefl', 'There are two ------- right next to the shopping mall.', '[{"id": "a", "text": "car park"}, {"id": "b", "text": "car parks"}, {"id": "c", "text": "cars park"}, {"id": "d", "text": "car''s parks"}]'::jsonb, 'b', 'Birleşik isimlerde çoğul eki normalde son kelimeye eklenir.', '[{"word": "çoğul + birleşik isim", "example": "bus stops", "meaning": "çoğul eki son kelimeye eklenir"}]'::jsonb, 'easy', true, 'en', 'compound-nouns', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('fcbd5582-623a-432d-9618-211349470497', 'yds', 'My ------- are coming to visit us this weekend.', '[{"id": "a", "text": "mother-in-laws"}, {"id": "b", "text": "mothers-in-law"}, {"id": "c", "text": "mother-in-law''s"}, {"id": "d", "text": "mothers-in-laws"}]'::jsonb, 'b', '''-in-law'' kalıplı birleşik isimlerde çoğul eki genellikle ilk kelimeye eklenir.', '[{"word": "mothers-in-law (istisna)", "example": "passers-by", "meaning": "çoğul ekinin ilk kelimeye eklendiği istisnai birleşik isimler"}]'::jsonb, 'medium', true, 'en', 'compound-nouns', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('602c19d5-9c72-4849-86e8-76a2ede9d8d6', 'yokdil', 'There were about fifty ------- grazing in the field.', '[{"id": "a", "text": "sheeps"}, {"id": "b", "text": "sheep"}, {"id": "c", "text": "a sheep"}, {"id": "d", "text": "sheep''s"}]'::jsonb, 'b', 'sheep tekil ve çoğul formda aynı kalır.', '[{"word": "sheep (değişmeyen çoğul)", "example": "fish, deer, sheep", "meaning": "tekil ve çoğulu aynı olan isimler"}]'::jsonb, 'easy', true, 'en', 'irregular-plurals', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('3f65ad96-ec47-4ba3-b0a4-8d52587d9272', 'ielts', 'Scientists are studying several unusual ------- related to climate change.', '[{"id": "a", "text": "phenomenons"}, {"id": "b", "text": "phenomena"}, {"id": "c", "text": "phenomenas"}, {"id": "d", "text": "phenomenon''s"}]'::jsonb, 'b', 'phenomenon''un düzensiz çoğul formu phenomena''dır.', '[{"word": "phenomenon → phenomena", "example": "crisis → crises", "meaning": "Latin/Yunan kökenli düzensiz çoğullar"}]'::jsonb, 'medium', true, 'en', 'irregular-plurals', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('70aaa0eb-1ad7-4304-8baa-29f108c6348c', 'yds', 'She sings very ------- ; everyone loves her voice.', '[{"id": "a", "text": "good"}, {"id": "b", "text": "well"}, {"id": "c", "text": "best"}, {"id": "d", "text": "better"}]'::jsonb, 'b', 'sings fiilini nitelemek için sıfat (good) değil zarf (well) kullanılır.', '[{"word": "well (zarf)", "example": "She sings well.", "meaning": "fiili niteleyen zarf"}]'::jsonb, 'easy', true, 'en', 'good-well-difference', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('83f28a98-e4cb-49a2-b9cc-6cafaf1a07bd', 'toefl', 'I don''t feel ------- today, I think I have a fever.', '[{"id": "a", "text": "good"}, {"id": "b", "text": "well"}, {"id": "c", "text": "nicely"}, {"id": "d", "text": "better"}]'::jsonb, 'b', 'Sağlık durumu anlatılırken well, feel fiilinden sonra sıfat olarak kullanılır.', '[{"word": "feel well (sağlık)", "example": "I don''t feel well.", "meaning": "sağlık durumunu anlatan sıfat kullanımı"}]'::jsonb, 'medium', true, 'en', 'good-well-difference', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('7663a544-a2d7-4bc1-b968-f8e30a4ee718', 'yokdil', 'This machine is ------- impossible to repair; we should just buy a new one.', '[{"id": "a", "text": "very"}, {"id": "b", "text": "quite"}, {"id": "c", "text": "so"}, {"id": "d", "text": "too"}]'::jsonb, 'b', 'impossible derecelenemeyen bir sıfattır; bu bağlamda quite ''tamamen'' anlamına gelir.', '[{"word": "quite + non-gradable", "example": "quite impossible", "meaning": "derecelenemeyen sıfatlarla ''tamamen'' anlamı"}]'::jsonb, 'medium', true, 'en', 'quite-rather-fairly', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('55bad0c4-521d-4e73-99c4-23bdc4441cb8', 'ielts', 'It''s ------- cold today, I didn''t bring a coat with me.', '[{"id": "a", "text": "quite"}, {"id": "b", "text": "rather"}, {"id": "c", "text": "so"}, {"id": "d", "text": "too"}]'::jsonb, 'b', 'Beklenmedik, olumsuz bir sürprizi vurgularken rather daha doğaldır.', '[{"word": "rather (beklenmedik sürpriz)", "example": "It''s rather expensive.", "meaning": "beklenenden fazla/olumsuz bir durumu vurgular"}]'::jsonb, 'medium', true, 'en', 'quite-rather-fairly', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('2f5238e7-e8ba-49ee-bed9-b21d20e86fcb', 'yds', 'This laptop is ------- that one, but it''s much cheaper.', '[{"id": "a", "text": "as fast as"}, {"id": "b", "text": "as faster as"}, {"id": "c", "text": "faster as"}, {"id": "d", "text": "so fast"}]'::jsonb, 'a', 'Eşitlik karşılaştırmasında as + yalın sıfat + as kalıbı kullanılır.', '[{"word": "as fast as (eşitlik)", "example": "as good as", "meaning": "iki şeyin eşit derecede olduğunu belirtir"}]'::jsonb, 'medium', true, 'en', 'as-as-comparison', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('4c8bf513-b54a-4dbc-8fa9-d235117928f1', 'toefl', 'He isn''t as tall ------- his older brother.', '[{"id": "a", "text": "than"}, {"id": "b", "text": "as"}, {"id": "c", "text": "that"}, {"id": "d", "text": "like"}]'::jsonb, 'b', 'as...as yapısında than değil as kullanılır.', '[{"word": "not as...as", "example": "not as difficult as", "meaning": "eşitsizlik/daha az olma durumu"}]'::jsonb, 'easy', true, 'en', 'as-as-comparison', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('67c8df28-5180-4c4e-a1b8-67aa364cdd8c', 'yokdil', 'The staff at this hotel are extremely -------.', '[{"id": "a", "text": "friendly"}, {"id": "b", "text": "friendlily"}, {"id": "c", "text": "friend"}, {"id": "d", "text": "friendliness"}]'::jsonb, 'a', 'friendly bir sıfattır, ''friendlily'' diye bir kelime yoktur.', '[{"word": "friendly (sıfat)", "example": "a friendly smile", "meaning": "-ly ile biten ama sıfat olan kelime"}]'::jsonb, 'hard', true, 'en', 'adjectives-ending-in-ly', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('6b374c94-5694-4d3a-ba9b-f53931edc9d0', 'yds', 'After the divorce, he felt very -------.', '[{"id": "a", "text": "lonely"}, {"id": "b", "text": "lonelily"}, {"id": "c", "text": "alonely"}, {"id": "d", "text": "lone"}]'::jsonb, 'a', 'lonely -ly ile bitmesine rağmen bir sıfattır.', '[{"word": "lonely (sıfat)", "example": "a lonely house", "meaning": "-ly ile biten ama sıfat olan kelime"}]'::jsonb, 'medium', true, 'en', 'adjectives-ending-in-ly', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('509f6443-fcc7-4ba7-a105-120fcc3c9b99', 'ielts', 'He has been working ------- all week, so he deserves a good rest.', '[{"id": "a", "text": "hard"}, {"id": "b", "text": "hardly"}, {"id": "c", "text": "harder"}, {"id": "d", "text": "hardness"}]'::jsonb, 'a', '''çok/sıkı çalışmak'' anlamı için hard kullanılır; hardly ''neredeyse hiç'' anlamına gelir.', '[{"word": "work hard", "example": "She studies hard.", "meaning": "çok/sıkı çalışmak"}]'::jsonb, 'medium', true, 'en', 'adverbs-of-manner-formation', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('dc8b6429-5d42-454e-8298-f7064a91a8e8', 'yds', 'The car drives very -------, it''s really powerful.', '[{"id": "a", "text": "fast"}, {"id": "b", "text": "fastly"}, {"id": "c", "text": "faster"}, {"id": "d", "text": "fastness"}]'::jsonb, 'a', 'fast hem sıfat hem zarf olarak aynı şekilde kullanılır, ''fastly'' diye bir kelime yoktur.', '[{"word": "fast (sıfat=zarf)", "example": "a fast car / drive fast", "meaning": "hem sıfat hem zarf olarak aynı form"}]'::jsonb, 'easy', true, 'en', 'adverbs-of-manner-formation', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('69fe3869-5490-440a-bf92-a88c6815eda2', 'yds', '------- I use your phone for a minute? Mine is out of battery.', '[{"id": "a", "text": "Must"}, {"id": "b", "text": "Could"}, {"id": "c", "text": "Should"}, {"id": "d", "text": "Need"}]'::jsonb, 'b', 'İzin isterken could kibar bir kullanımdır.', '[{"word": "could (kibar izin isteme)", "example": "Could I sit here?", "meaning": "can''e göre daha kibar izin isteme"}]'::jsonb, 'easy', true, 'en', 'modals-permission-requests', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('983c5900-06a3-41f5-bfaf-e1b23c1de225', 'toefl', '------- you help me carry these boxes upstairs, please?', '[{"id": "a", "text": "May"}, {"id": "b", "text": "Could"}, {"id": "c", "text": "Should"}, {"id": "d", "text": "Must"}]'::jsonb, 'b', 'Rica ederken could/can kullanılır; may genellikle izin istemek için tercih edilir.', '[{"word": "could you...? (rica)", "example": "Could you pass the salt?", "meaning": "kibar bir ricada bulunma kalıbı"}]'::jsonb, 'medium', true, 'en', 'modals-permission-requests', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('9e6cf3c3-6e74-43e2-8589-0cefb07b802e', 'yds', 'Yesterday, I ------- go to the dentist because of a terrible toothache.', '[{"id": "a", "text": "must"}, {"id": "b", "text": "had to"}, {"id": "c", "text": "have to"}, {"id": "d", "text": "must have"}]'::jsonb, 'b', 'must''ın geçmiş zaman formu yoktur, geçmişte zorunluluk için had to kullanılır.', '[{"word": "had to (geçmiş zorunluluk)", "example": "I had to leave early.", "meaning": "must''ın geçmiş karşılığı"}]'::jsonb, 'medium', true, 'en', 'must-vs-have-to', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('334fd8e0-0680-4ccd-b1ff-aef3321cebbf', 'yokdil', 'I really ------- call my grandmother today, I miss her so much.', '[{"id": "a", "text": "have to"}, {"id": "b", "text": "must"}, {"id": "c", "text": "had"}, {"id": "d", "text": "has to"}]'::jsonb, 'b', 'Kişisel görüşe/isteğe dayanan zorunluluk must ile ifade edilir.', '[{"word": "must (kişisel zorunluluk)", "example": "I must call her.", "meaning": "konuşanın kendi görüşüne dayanan zorunluluk"}]'::jsonb, 'hard', true, 'en', 'must-vs-have-to', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('e38e489f-ad9f-4811-b32d-57315ae5fd35', 'ielts', 'You ------- worry about the exam, you''ve prepared really well.', '[{"id": "a", "text": "mustn''t"}, {"id": "b", "text": "needn''t"}, {"id": "c", "text": "can''t"}, {"id": "d", "text": "haven''t"}]'::jsonb, 'b', 'Gereklilik olmadığı anlatıldığı için needn''t kullanılır.', '[{"word": "needn''t (gereksiz)", "example": "You needn''t hurry.", "meaning": "bir şeyin yapılmasının gerekmediğini anlatır"}]'::jsonb, 'medium', true, 'en', 'neednt-vs-mustnt', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('48c49e31-8eb1-4810-9d88-db60abe3cb12', 'yds', 'You ------- reveal this information to anyone, it''s strictly confidential.', '[{"id": "a", "text": "needn''t"}, {"id": "b", "text": "mustn''t"}, {"id": "c", "text": "don''t have to"}, {"id": "d", "text": "may"}]'::jsonb, 'b', 'Kesin bir yasak söz konusu olduğu için mustn''t kullanılmalıdır.', '[{"word": "mustn''t (yasak)", "example": "You mustn''t smoke here.", "meaning": "kesinlikle yapılmaması gereken bir şeyi anlatır"}]'::jsonb, 'medium', true, 'en', 'neednt-vs-mustnt', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('2c5c0808-efa9-4e85-adf9-9a38b781eef3', 'toefl', 'You ------- take an umbrella, it looks like it''s going to rain.', '[{"id": "a", "text": "had better"}, {"id": "b", "text": "would rather"}, {"id": "c", "text": "must to"}, {"id": "d", "text": "should to"}]'::jsonb, 'a', 'Olumsuz bir sonuç riskiyle birlikte güçlü bir tavsiye verildiği için had better kullanılır.', '[{"word": "had better (güçlü tavsiye)", "example": "You''d better see a doctor.", "meaning": "yapılmazsa olumsuz sonuç doğabilecek tavsiye"}]'::jsonb, 'medium', true, 'en', 'had-better-would-rather', 'system', 'approved');
INSERT INTO exam_questions (id, exam_type, question_text, options, correct_option, explanation, related_words, difficulty_level, is_active, learning_lang, topic_tag, source_type, status) VALUES ('5c5fb5f1-b15a-4ee9-a6dd-b97667ffd89d', 'yds', 'I ------- stay home tonight than go to the party.', '[{"id": "a", "text": "had better"}, {"id": "b", "text": "would rather"}, {"id": "c", "text": "must"}, {"id": "d", "text": "should"}]'::jsonb, 'b', 'İki seçenek arasında bir tercih belirtildiği için would rather kullanılır.', '[{"word": "would rather...than", "example": "I''d rather walk than drive.", "meaning": "iki seçenek arasında tercih belirtir"}]'::jsonb, 'easy', true, 'en', 'had-better-would-rather', 'system', 'approved');
